public CompletableFuture<BookingResponse> aggregateBooking(BookingRequest request) {
    CompletableFuture<FlightResponse> flightFuture = 
        CompletableFuture.supplyAsync(() -> flightServiceClient.reserve(request));
    CompletableFuture<HotelResponse> hotelFuture = 
        CompletableFuture.supplyAsync(() -> hotelServiceClient.reserve(request));

    return CompletableFuture.allOf(flightFuture, hotelFuture)
        .thenApply(v -> new BookingResponse(flightFuture.join(), hotelFuture.join()))
        .exceptionally(ex -> {
            compensatePartialReservations(request);
            throw new BookingFailedException("Failed to complete reservation", ex);
        });
}
